/bin/zsh -lc "node --input-type=module <<'JS'
import { readFileSync } from 'node:fs';
import assert from 'node:assert/strict';
const kb = JSON.parse(readFileSync('server/kristy_perimeter_kb.json', 'utf8'));
const review = readFileSync('docs/do-lines-review.md', 'utf8');
const lines = JSON.parse(readFileSync('server/lib/doLines.json', 'utf8'));
const expected = {
 egg_labels: 'Find all three words on one carton, plus a certifier’s pasture seal.',
 whole_vs_reduced_fat_milk: 'Check the side panel for the pasteurization words and a grass-fed seal.',
 yogurt_plain_vs_flavored: 'Check the ingredients for milk and cultures, with nothing after them.',
 grassfed_butter: 'Look through the wrapper window before choosing a block.',
};
for (const [id, line] of Object.entries(expected)) {
 const row = review.split('\\n').find(s => s.startsWith("'`| '"\\"'`${id}'"\\"'` | eggs_dairy |`));
 assert.ok(row, `${id}: review row missing`);
 assert.equal(row.split('"'|')[3].trim(), kb.entries.find(e => e.id === id).decision, "'`${id}: headline`);
 assert.equal(row.split('"'|')[4].trim(), line, "'`${id}: reviewed do`);
 assert.equal(lines[id], line, `${id}: generated do`);
}
console.log('"'All four reviewed headlines and reviewed/generated do lines match the spec.');
JS"

